using System.Text.Json.Nodes;
using Lite.Conformance.Harness;
using Lite.Conformance.Wpt;

namespace Lite.Conformance.Css21;

/// <summary>Decides a self-describing CSS 2.1 case. The no-red scan is necessary but proves
/// a pass only where the stated condition is solely "no red"
/// (<c>Css21/css21-pass-conditions.json</c>, generated by
/// <c>scripts/gen_css21_pass_conditions.py</c>). Every other red-scan pass needs a stronger
/// oracle: the WPT reftest twin (<see cref="OfficialTwinOracle"/>), the embedded
/// #test/#reference swatch pair for "same color" cases, a machine check of the stated
/// condition (<see cref="VisualChecks"/>), or — until a reviewed reference or manual
/// evidence exists — it is reported unsupported, never passed.</summary>
internal static class SelfTestOracle
{
    internal const string ConditionsFile = "Css21/css21-pass-conditions.json";

    internal sealed record Stated(string Condition, string? Sentence, VisualCheck? Check, bool ManualPending = false);

    private static Dictionary<string, Stated>? _conditions;

    internal static WptRunner.RunResult Run(WptCase test, IReadOnlyList<WptCase> catalog, Func<string, WptCase?> lookup)
    {
        var stated = Condition(test.Path);
        var twin = OfficialTwinOracle.Find(test.Path, catalog);
        // A twin is the stronger oracle; the stated-condition check decides only without one.
        var check = twin is null && stated is { Check: { } c, Sentence: { } sentence }
            ? (Func<RenderSet, Lite.Models.LayoutNode, WptRunner.RunResult>)((renders, root) =>
                VisualChecks.Evaluate(c, renders, root, sentence, test.Path))
            : null;
        var result = WptVisualPage.RunSelfTest(test, embeddedRequired: stated.Condition == "same-color",
            statedCondition: check, statedCheck: stated.Check);
        return Decide(test.Path, stated.Condition, result, twin, lookup, checkedCondition: check is not null,
            manualPending: stated.ManualPending);
    }

    internal static WptRunner.RunResult Decide(string path, string condition, WptRunner.RunResult selfTest,
        OfficialTwinOracle.Twin? twin, Func<string, WptCase?> lookup, bool checkedCondition = false,
        bool manualPending = false)
    {
        if (!selfTest.Passed) return selfTest;
        if (twin is not null) return OfficialTwinOracle.Strengthen(twin, path, selfTest, lookup);
        if (checkedCondition || condition is "no-red" or "same-color") return selfTest;
        if (manualPending)
            return new(WptRunner.Cat.ManualPending,
                "Reviewed: the stated condition needs native observation (cursor shape, hover/activate state, " +
                "viewport resize or scrollbar interaction) — awaiting recorded manual evidence", 0, 0, Artifacts: selfTest.Artifacts);
        return new(WptRunner.Cat.Unsupported,
            $"Stated pass condition '{condition}' is not machine-checked by the no-red scan; needs a reviewed reference or manual evidence",
            0, 0, Artifacts: selfTest.Artifacts);
    }

    /// <summary>The case's classified pass condition; an unlisted case is "unstated",
    /// which no red-scan pass can satisfy on its own.</summary>
    internal static Stated Condition(string path)
    {
        _conditions ??= Load();
        return _conditions.GetValueOrDefault(path) ?? new("unstated", null, null);
    }

    private static Dictionary<string, Stated> Load()
    {
        var file = ConformancePaths.Manifest(ConditionsFile);
        if (!File.Exists(file)) return new(StringComparer.Ordinal);
        return JsonNode.Parse(File.ReadAllText(file))!["cases"]!.AsArray().OfType<JsonObject>()
            .ToDictionary(c => c["path"]!.GetValue<string>(), c => new Stated(
                c["condition"]!.GetValue<string>(), c["sentence"]?.GetValue<string>(), ReadCheck(c["check"] as JsonObject),
                c["manualPending"]?.GetValue<bool>() ?? false),
                StringComparer.Ordinal);
    }

    private static VisualCheck? ReadCheck(JsonObject? check) => check is null ? null : new(
        check["kind"]!.GetValue<string>(), check["shape"]?.GetValue<string>(), check["color"]?.GetValue<string>(),
        check["dimension"]?.GetValue<string>(), check["count"]?.GetValue<int>(),
        check["colorA"]?.GetValue<string>(), check["colorB"]?.GetValue<string>(),
        check["relation"]?.GetValue<string>(), check["lineColor"]?.GetValue<string>(),
        check["over"]?.GetValue<bool>(), check["under"]?.GetValue<bool>(), check["through"]?.GetValue<bool>(),
        check["variant"]?.GetValue<string>(), check["firstShape"]?.GetValue<string>(), check["firstColor"]?.GetValue<string>(),
        check["secondShape"]?.GetValue<string>(), check["secondColor"]?.GetValue<string>(), check["arrangement"]?.GetValue<string>(),
        check["approx"]?.GetValue<bool>() ?? false, check["anchor"]?.GetValue<string>(),
        check["colorC"]?.GetValue<string>(), check["bulletColor"]?.GetValue<string>(), check["needle"]?.GetValue<string>(),
        check["side"]?.GetValue<string>(), check["edge"]?.GetValue<string>(), check["span"]?.GetValue<string>(),
        check["mode"]?.GetValue<string>(), check["scope"]?.GetValue<string>(),
        check["even"]?.GetValue<bool>() ?? false, check["shades"]?.GetValue<bool>() ?? false,
        check["marker"]?.GetValue<bool>() ?? false, check["bullet"]?.GetValue<string>(),
        check["rows"]?.GetValue<int>(), check["cols"]?.GetValue<int>(),
        check["colors"] is { } colors ? [.. colors.AsArray().Select(c => c!.GetValue<string>())] : null,
        check["needles"] is { } needles ? [.. needles.AsArray().Select(n => n!.GetValue<string>())] : null,
        check["sides"] is { } sides ? sides.AsObject().ToDictionary(
            kv => kv.Key, kv => new SideSpec(kv.Value!["shape"]?.GetValue<string>(), kv.Value!["color"]?.GetValue<string>())) : null,
        check["ordered"]?.GetValue<bool>() ?? false, check["boxColor"]?.GetValue<string>(),
        check["target"]?.GetValue<string>(),
        check["scroll"] is { } scroll ? new ScrollSpec(scroll["to"]?.GetValue<string>() ?? "bottom") : null);
}
